"use client";

import { useEffect, useRef, useState } from "react";

const TARGET = 12480;
const DURATION = 1400;

function easeOutCubic(progress: number) {
  return 1 - Math.pow(1 - progress, 3);
}

export default function Demo() {
  const containerRef = useRef<HTMLDivElement>(null);
  const [value, setValue] = useState(0);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setValue(TARGET);
      return;
    }

    let frame = 0;
    let started = false;

    const observer = new IntersectionObserver(
      (entries) => {
        if (started || !entries.some((entry) => entry.isIntersecting)) return;
        started = true;
        const start = performance.now();

        const tick = (now: number) => {
          const progress = Math.min((now - start) / DURATION, 1);
          setValue(Math.round(easeOutCubic(progress) * TARGET));
          if (progress < 1) frame = requestAnimationFrame(tick);
        };

        frame = requestAnimationFrame(tick);
      },
      { threshold: 0.4 }
    );

    observer.observe(container);

    return () => {
      observer.disconnect();
      cancelAnimationFrame(frame);
    };
  }, []);

  return (
    <div
      ref={containerRef}
      className="w-full max-w-sm rounded-2xl border border-zinc-200 bg-gradient-to-br from-white to-zinc-50 p-7 text-center dark:border-zinc-800 dark:from-zinc-950 dark:to-zinc-900"
    >
      <p className="text-[11px] uppercase tracking-[0.24em] text-zinc-500 dark:text-zinc-400">
        Monthly downloads
      </p>
      <p className="mt-3 font-mono text-4xl font-semibold tabular-nums text-zinc-900 dark:text-white">
        {value.toLocaleString("en-US")}
        <span className="text-emerald-500">+</span>
      </p>
      <p className="mt-2 text-sm text-zinc-500 dark:text-zinc-400">
        进入视口后开始计数，只播放一次。
      </p>
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { Check, Copy, TriangleAlert } from "lucide-react";

const CODE = "npx create-next-app@latest";

export default function Demo() {
  const [state, setState] = useState<"idle" | "copied" | "error">("idle");
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      if (timerRef.current !== null) window.clearTimeout(timerRef.current);
    };
  }, []);

  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(CODE);
      setState("copied");
    } catch {
      setState("error");
    }

    if (timerRef.current !== null) window.clearTimeout(timerRef.current);
    timerRef.current = window.setTimeout(() => setState("idle"), 1800);
  }

  return (
    <div className="w-full max-w-sm">
      <div className="flex items-center gap-2 rounded-xl border border-zinc-200 bg-zinc-50 p-1.5 pl-4 dark:border-zinc-800 dark:bg-zinc-900">
        <code className="min-w-0 flex-1 truncate font-mono text-[13px] text-zinc-700 dark:text-zinc-200">
          {CODE}
        </code>
        <button
          type="button"
          onClick={handleCopy}
          aria-live="polite"
          className="inline-flex h-9 shrink-0 items-center gap-1.5 rounded-lg bg-white px-3 text-xs font-medium text-zinc-700 shadow-sm ring-1 ring-zinc-200 transition hover:text-zinc-950 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-400/60 dark:bg-zinc-800 dark:text-zinc-200 dark:ring-zinc-700 dark:hover:text-white"
        >
          {state === "copied" ? (
            <>
              <Check className="h-3.5 w-3.5 text-emerald-500" aria-hidden="true" />
              Copied
            </>
          ) : state === "error" ? (
            <>
              <TriangleAlert className="h-3.5 w-3.5 text-amber-500" aria-hidden="true" />
              Retry
            </>
          ) : (
            <>
              <Copy className="h-3.5 w-3.5" aria-hidden="true" />
              Copy
            </>
          )}
        </button>
      </div>
      <p className="mt-2 text-xs text-zinc-500 dark:text-zinc-400">
        复制失败时保留可重试状态，而不是静默失败。
      </p>
    </div>
  );
}

