                </button>
              </li>
            ))}
          </ul>

          <div className="flex items-center gap-2">
            <a
              href="#"
              className="hidden rounded-full bg-zinc-900 px-4 py-1.5 text-sm font-medium text-white transition hover:bg-zinc-700 dark:bg-white dark:text-zinc-900 dark:hover:bg-zinc-200 sm:inline-flex"
            >
              Sign in
            </a>
            <button
              type="button"
              onClick={() => setOpen((value) => !value)}
              aria-expanded={open}
              aria-controls="floating-navbar-menu"
              aria-label="Toggle menu"
              className="grid h-9 w-9 place-items-center rounded-full border border-zinc-200 text-zinc-700 md:hidden dark:border-zinc-700 dark:text-zinc-200"
            >
              <Menu className="h-4 w-4" aria-hidden="true" />
            </button>
          </div>
        </nav>

        {open && (
          <ul
            id="floating-navbar-menu"
            className="mt-3 space-y-1 rounded-2xl border border-zinc-200 bg-white p-2 shadow-lg md:hidden dark:border-zinc-800 dark:bg-zinc-900"
          >
            {links.map((link) => (
              <li key={link}>
                <button
                  type="button"
                  onClick={() => {
                    setActive(link);
                    setOpen(false);
                  }}
                  className="w-full rounded-xl px-3 py-2 text-left text-sm text-zinc-700 hover:bg-zinc-100 dark:text-zinc-200 dark:hover:bg-zinc-800"
                >
                  {link}
                </button>
              </li>
            ))}
          </ul>
        )}
      </header>
    </section>
  );
}

